views 'C2' {
  view c2_corePlatform {
    title 'Core Platform - Containers'
    description 'System boundary, containers, user, and email integration'

    include user
    include externalEmailService

    include corePlatform
    include corePlatform.*

    include corePlatform.webApp with {
      navigateTo c3_webApp
    }
  }
}

views 'Use Cases' {
  dynamic view uploadJourney {
    title 'Upload Journey'

    user -> browser 'Select file'
    browser -> corePlatform.webApp 'Open upload page'
    corePlatform.webApp -> corePlatform.api 'POST /uploads'
    corePlatform.api -> corePlatform.uploadService 'Validate request'
    corePlatform.uploadService -> corePlatform.objectStorage 'Store file'
  }
}

views 'Operations' {
  deployment view secZone_overview {
    title 'Production Security Zone'
    description 'Bastion, firewall, and dedicated security services in production'

    include production
    include production.secZone

    include production.secZone.bastionVm
    include production.secZone.firewallVm
    include production.secZone.monitoringVm
    include production.secZone.loggingVm
  }
}
